"""Build the write-up PDF: the five graded pages (docs/writeup/writeup.md), then the appendices generated by
scripts/exhibits_part2.py and the AI log rendered from ai/ai_log.json.

Run: .venv/Scripts/python.exe -I scripts/build_writeup.py
Writes docs/writeup/writeup.html, docs/writeup/ai_log.md and docs/writeup/writeup.pdf (printed by Chrome or Edge in
headless mode), and reports the page count of the graded part, which must be 5 or fewer.
"""
from __future__ import annotations

import json
import re
import shutil
import subprocess
import tempfile
from pathlib import Path

import markdown

ROOT = Path(__file__).resolve().parents[1]
W = ROOT / "docs" / "writeup"
BROWSERS = [r"C:\Program Files\Google\Chrome\Application\chrome.exe", r"C:\Program Files (x86)\Microsoft\Edge\Application\msedge.exe",
            "google-chrome", "chromium", "msedge"]
CSS = """
@page { size: Letter; margin: 0.6in 0.65in; }
body { font-family: "Segoe UI", Calibri, Arial, sans-serif; font-size: 9.6pt; line-height: 1.32; color: #1a1a1a; }
h1 { font-size: 15pt; margin: 0 0 4pt; }
h2 { font-size: 12pt; margin: 10pt 0 3pt; border-bottom: 1px solid #999; }
h3 { font-size: 10.5pt; margin: 8pt 0 2pt; }
p { margin: 3pt 0 4pt; }
table { border-collapse: collapse; width: 100%; font-size: 8.3pt; margin: 3pt 0 2pt; page-break-inside: avoid; }
th, td { border: 1px solid #bbb; padding: 1.5pt 4pt; vertical-align: top; text-align: left; }
th { background: #eef1f5; }
blockquote { margin: 3pt 0 6pt; padding: 3pt 8pt; background: #f6f6f2; border-left: 3px solid #8a8a70; font-size: 8.8pt; }
blockquote p { margin: 0; }
em { color: #444; }
.break { page-break-before: always; }
img { max-width: 100%; }
code { font-size: 8.5pt; }
"""


def ai_log_md() -> str:
    log = json.loads((ROOT / "ai" / "ai_log.json").read_text(encoding="utf-8"))["entries"]
    out = ["# Appendix E. The AI log", "",
           f"*Rendered from `ai/ai_log.json` by `scripts/build_writeup.py`: {len(log)} exchanges that changed a decision, in order.*", ""]
    for e in log:
        out += [f"### {e['id']}. {e['stage']} ({e['role']}; raised by {e['proposed_by']})", ""]
        for k, name in (("question", "Question"), ("ai_answer", "AI answer"), ("challenge", "Challenge"), ("test", "Test"),
                        ("result", "Result"), ("decision", "Decision"), ("effect", "Effect")):
            if e.get(k):
                out.append(f"**{name}.** {e[k]}  ")
        out.append("")
    return "\n".join(out) + "\n"


def html(md_text: str, title: str) -> str:
    body = markdown.markdown(md_text, extensions=["tables", "sane_lists"])
    return f"<!doctype html><html><head><meta charset='utf-8'><title>{title}</title><style>{CSS}</style></head><body>{body}</body></html>"


def browser() -> str:
    for b in BROWSERS:
        if Path(b).exists() or shutil.which(b):
            return b
    raise SystemExit("no Edge or Chrome found to print the PDF")


def to_pdf(src: Path, dst: Path) -> int:
    with tempfile.TemporaryDirectory() as prof:                    # its own profile, so a running browser does not swallow the job
        subprocess.run([browser(), "--headless=new", "--disable-gpu", "--no-pdf-header-footer", f"--user-data-dir={prof}",
                        f"--print-to-pdf={dst}", src.as_uri()], check=True, capture_output=True)
    return len(re.findall(rb"/Type\s*/Page[^s]", dst.read_bytes()))


def main() -> None:
    main_md = (W / "writeup.md").read_text(encoding="utf-8")
    ex = (W / "exhibits" / "part2_final.md").read_text(encoding="utf-8")
    ex = ex.split("\n", 1)[1].replace("](part2_", "](exhibits/part2_")         # drop the generated file's own title
    ex = ex.replace("## Exhibit P2-", "### Exhibit D").replace("## Appendix", "## Appendix")
    apps, ladder = [], []
    for block in re.split(r"(?m)^(?=## |### Exhibit D)", ex):
        (apps if block.startswith("## Appendix") else ladder).append(block)
    log = ai_log_md()
    (W / "ai_log.md").write_text(log, encoding="utf-8", newline="\n")
    appendix = "\n".join(a.replace("## Appendix", "# Appendix") for a in apps if a.strip())
    appendix += "\n# Appendix D. Part 2 evidence\n\n" + "\n".join(ladder) + "\n" + log
    graded = W / "writeup_graded.html"
    graded.write_text(html(main_md, "Write-up"), encoding="utf-8", newline="\n")
    n_graded = to_pdf(graded, W / "writeup_graded.pdf")
    full = W / "writeup.html"
    full.write_text(html(main_md + "\n<div class='break'></div>\n\n" + appendix, "Write-up"), encoding="utf-8", newline="\n")
    n_full = to_pdf(full, W / "writeup.pdf")
    graded.unlink()
    (W / "writeup_graded.pdf").unlink()
    print(f"graded part: {n_graded} pages (limit 5); whole PDF: {n_full} pages -> {W / 'writeup.pdf'}")


if __name__ == "__main__":
    main()
